const cfg = $item(0).$node['Config'].json;
const j = items?.[0]?.json ?? {};

const defaultSeed = [
  'https://www.melnick.com.br/enterprise/go-bom-fim-2/',
  'https://www.melnick.com.br/enterprise/high-garden-rio-branco/',
  'https://www.melnick.com.br/enterprise/go-home-design/'
];

let seeded = defaultSeed;
try {
  const parsed = JSON.parse(String(cfg.seedUrlsJson || '[]'));
  if (Array.isArray(parsed) && parsed.length) seeded = parsed;
} catch (e) {
  seeded = defaultSeed;
}

const statusCode = Number(j.statusCode ?? 200);
const raw = j.body ?? j.data ?? j.response ?? '';
const body = typeof raw === 'string' ? raw : JSON.stringify(raw || '');

const regex = /https:\/\/www\.melnick\.com\.br\/enterprise\/[A-Za-z0-9\-_/]+/gi;
const urls = new Set();

while (true) {
  const m = regex.exec(body);
  if (!m) break;
  const clean = m[0].replace(/["'<>]/g, '').replace(/\/$/, '') + '/';
  urls.add(clean);
}

for (const s of seeded) {
  if (typeof s === 'string' && s.includes('/enterprise/')) {
    urls.add(s.replace(/\/$/, '') + '/');
  }
}

const links = [...urls].slice(0, Number(cfg.maxEmpreendimentos ?? 40));

if (!links.length) {
  return seeded.map((empreendimentoUrl, i) => ({
    json: {
      indice: i + 1,
      totalLinks: seeded.length,
      empreendimentoUrl,
      origem: 'fallback_seed_urls',
      motivo: `status=${statusCode}`
    }
  }));
}

const origem = (statusCode >= 500 || body.length < 500)
  ? 'html_com_fallback_seed'
  : 'html_empreendimentos';

return links.map((empreendimentoUrl, i) => ({
  json: {
    indice: i + 1,
    totalLinks: links.length,
    empreendimentoUrl,
    origem
  }
}));

const src = $json;
const empreendimentoUrl = src.empreendimentoUrl || src.url || null;
const raw = src.body ?? src.data ?? src.response ?? '';
const html = typeof raw === 'string' ? raw : JSON.stringify(raw || '');

const titleMatch = html.match(/<h1[^>]*>(.*?)<\/h1>/is);
const nome = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : null;

const imgRegex = /https?:\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|webp|gif)(?:\?[^"'<>\s]+)?/gi;
const all = new Set();
while (true) {
  const m = imgRegex.exec(html);
  if (!m) break;
  const u = String(m[0]).replace(/&amp;/g, '&');
  if (u.includes('data:image')) continue;
  all.add(u);
}

const rawImageUrls = [...all].sort();

const plantas = rawImageUrls.filter((u) => /planta|floor|tipologia|implantacao|implanta/i.test(u));
const caracteristicas = rawImageUrls.filter((u) => /icone|icon|caracteristica|feature|amenit/i.test(u) && !plantas.includes(u));
const galeria = rawImageUrls.filter((u) => /galeria|gallery|fachada|decorado|interna|externa|lazer|piscina|rooftop|living|suite|dormitorio/i.test(u) && !plantas.includes(u) && !caracteristicas.includes(u));
const outras = rawImageUrls.filter((u) => !plantas.includes(u) && !galeria.includes(u) && !caracteristicas.includes(u));

return [{
  json: {
    nome,
    url: empreendimentoUrl,
    totalImagens: rawImageUrls.length,
    rawImageUrls,
    galeria,
    plantas,
    caracteristicas,
    outras,
    origemClassificacao: 'heuristica_core'
  }
}];
